#include <memory>

class Resource {};

void dangerous_usage() {
    // DANGER: new[] used, but auto_ptr uses delete
    std::auto_ptr<Resource> ap_bad(new Resource[5]); 
    // UB when ap_bad goes out of scope and calls delete
}

void correct_usage() {
    // Correct: new used, auto_ptr calls delete
    std::auto_ptr<Resource> ap_good(new Resource);
}

// Note: std::unique_ptr<Resource[]> should be used today.
